<template>
    <div id="map" style="height:100%; width:100%">
    </div>
</template>
  
<script>
  import L from 'leaflet';
  import 'leaflet/dist/leaflet.css';
  import 'leaflet.heat'
  import axios from 'axios';

  import markerIcon2x from 'leaflet/dist/images/marker-icon-2x.png';
  import markerIcon from 'leaflet/dist/images/marker-icon.png';
  import markerShadow from 'leaflet/dist/images/marker-shadow.png';

  delete L.Icon.Default.prototype._getIconUrl;

L.Icon.Default.mergeOptions({
  iconRetinaUrl: markerIcon2x,
  iconUrl: markerIcon,
  shadowUrl: markerShadow,
});

  export default {
    data() {
      return {
        map: null,
        thdValue:0.0,
        thdCircles:[],
        polling:null,
      };
    },
    name: 'LeafletMap',
    mounted(){
      const { center, zoom } = this.getMapCenter(this.$route.path);

      //change center based on the current route

      this.map = L.map('map').setView(center, zoom); //17 @ manchester city,  12 @ manchester, 5 @ UK

      L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        attribution: '&copy; OpenStreetMap contributors',
      }).addTo(this.map);

      this.addMapFeatures();
    
  const legend = L.control({ position: 'bottomright' });

legend.onAdd = function () {
  const div = L.DomUtil.create('div', 'info legend');
  div.innerHTML = `
    <h4>Legend</h4>
    <i style="background: red"></i> THD>10% <br>
    <i style="background: yellow"></i> THD<10% <br>
    <i style="background: green"></i> THD<5% <br>
  `;
  return div;
};

legend.addTo(this.map);


      setTimeout(() => {
    this.map.invalidateSize();
  }, 300);

    window.addEventListener('resize', this.handleResize);
    window.addEventListener('orientationchange', this.handleResize);

    this.fetchTHDData();
    this.polling = setInterval(this.fetchTHDData,3000); // fetch data every 3 seconds
    },
  watch: {
    '$route.path'(newPath) {
      const { center, zoom } = this.getMapCenter(newPath);
      this.map.setView(center, zoom); // update map center

      this.map.eachLayer((layer) => {
        if (layer instanceof L.Marker || layer instanceof L.Circle) {
          this.map.removeLayer(layer);
        }
      });
      this.addMapFeatures();
    },
    thdValue(newVal){
      const color = this.getTHDColor(newVal);

      this.thdCircles.forEach(circle => {
        circle.setStyle({
          fillColor: color,
          fillOpacity:0.6,
        });
      })
    }
  },
  methods: {
    handleResize() {
      if (this.map) {
        setTimeout(() => {
          this.map.invalidateSize();
        }, 300); // Delay ensures layout has updated
      }
    },
    getMapCenter(path){
      switch (path){
        case '/device1': return { center: [53.4692, -2.2340], zoom: 17 }; //Manchester, Nancy Rothwell building
        case '/device2': return { center: [53.4690, -2.2342], zoom: 17 }; //Manchester 2
        case '/device3': return { center: [53.4694, -2.2338], zoom: 17 }; //Manchester 3
        case '/device4': return { center: [53.4693, -2.2344], zoom: 17 }; //Manchester 4
        case '/device5': return { center: [53.4690, -2.2346], zoom: 17 }; //Manchester 5
        default: return { center: [53.4839, -2.2446], zoom: 17 };
      }
    },
    addMapFeatures() {

    const path = this.$route.path;
    const locations = [
      { name:'Manchester 1', lat:53.4692, lng:-2.2340, route:'/device1' },
      { name:'Manchester 2', lat:53.4690, lng:-2.2342, route:'/device2' },
      { name:'Manchester 3', lat:53.4694, lng:-2.2338, route:'/device3' },
      { name:'Manchester 4', lat:53.4693, lng:-2.2344, route:'/device4' },
      { name:'Manchester 5', lat:53.4690, lng:-2.2346, route:'/device5' },
    ];

    this.thdCircles = [];

    locations.forEach((loc) => {
      const marker = L.marker([loc.lat,loc.lng]).addTo(this.map).bindPopup(loc.name);

      marker.on('click', () => this.$router.push(loc.route));

      
      if (loc.route === path) {
        const circle = L.circle([loc.lat, loc.lng],{
          radius:10,
          color:'#000',
          weight: 1,
          fillColor: this.getTHDColor(this.thdValue),
          fillOpacity:0.6,
        }).addTo(this.map);

        this.thdCircles.push(circle);
      }
    })
      //Add markers here
    /*  const marker1 = L.marker([53.4692, -2.2340]).addTo(this.map).bindPopup('Manchester');
      marker1.on('click', () => {
    this.$router.push('/device1'); // or use window.location.href = '/page-a' if not using Vue Router
          
  });
      const marker2 = L.marker([55.9533, -3.1883]).addTo(this.map).bindPopup('Edinburgh');

      marker2.on('click', () => {
    this.$router.push('/device2'); // or use window.location.href = '/page-a' if not using Vue Router
          
  });
      const marker3 = L.marker([51.5072, -0.1276]).addTo(this.map).bindPopup('London');

      marker3.on('click', () => {
    this.$router.push('/device3'); // or use window.location.href = '/page-a' if not using Vue Router
          
  });
      const marker4 = L.marker([51.4545, -2.5879]).addTo(this.map).bindPopup('London');

      marker4.on('click', () => {
    this.$router.push('/device4'); // or use window.location.href = '/page-a' if not using Vue Router
          
  });
      const marker5 = L.marker([53.3811, -1.4701]).addTo(this.map).bindPopup('London');

      marker5.on('click', () => {
    this.$router.push('/device5'); // or use window.location.href = '/page-a' if not using Vue Router
          
  }); */

      //Add heatmap here [lat,ltg,intensity]
     /* const heatData = [
      [53.4692, -2.2340, 0.91], //Manchester
      [55.9533, -3.1883, 0.91], //Edinburgh
      [51.5072, -0.1276, 0.91], //London
      [51.4545, -2.5879, 0.91], //Bristol
      [53.3811, -1.4701, 0.91], //Sheffield
      // Add more if needed
    ];

    L.heatLayer(heatData, {
      radius: 25,
      blur: 20,
      maxZoom: 17,
    }).addTo(this.map); */
    },
    async fetchTHDData(){
      try {
        const path = this.$route.path;
        const deviceId = path.replace('/','');
        if (!deviceId.startsWith('device')) return;

        const endpoint = `https://api.ch-data.xyz/api/${deviceId}/thd`;
        const response = await axios.get(endpoint);
        const thd = parseFloat(response.data.THD);
        this.thdValue = thd;
      } catch (err) {
        console.error('Failed to fetch THD for route:',this.$route.path, err)
      }
    },
    getTHDColor(thd) {
      if (thd > 0.10) return 'red';
      if (thd > 0.05) return 'yellow';
      return 'green';
    }
  },
  beforeUnmount() {
    // 🧹 Clean up listeners
    window.removeEventListener('resize', this.handleResize);
    window.removeEventListener('orientationchange', this.handleResize);

    if (this.polling) clearInterval(this.polling);

    if (this.map) {
      this.map.remove(); // Properly remove the map
      this.map = null;
    }
  }
  };
</script>
  
<style>
.info.legend {
  background: white;
  padding: 6px 8px;
  font: 14px Arial, sans-serif;
  box-shadow: 0 0 15px rgba(0,0,0,0.2);
  border-radius: 5px;
  line-height: 18px;
  color: #555;
}
.info.legend i {
  width: 18px;
  height: 18px;
  float: left;
  margin-right: 8px;
  opacity: 0.7;
}
</style>